class ParseNoteSeparatorTests(unittest.TestCase):
    def test_separator_kept_inside_note(self):
        for ch in ("\x0c", "\u2028", "\u2029", "\x85", "\x0b", "\x1c"):
            text = "2024-03-01 a 1 note%swith sep\n2024-03-02 b 2\n" % ch
            entries = pennywise.parse(text)
            self.assertEqual(len(entries), 2, repr(ch))
            self.assertEqual(entries[0].note, "note%swith sep" % ch)
            self.assertEqual(entries[1].category, "b")

    def test_form_feed_example_from_issue(self):
        (e,) = pennywise.parse("2024-03-01 a 1 note\x0cwith ff\n")
        self.assertIn("\x0c", e.note)


if __name__ == "__main__":
    unittest.main()
        self.assertEqual((code, out), (0, "2024-03-09 x 5.00 -refund\n"))

    def test_added_line_parses_back(self):
        run(["add", self.path, "2024-03-09", "x", "5", "a  b"])
        self.assertEqual(run(["list", self.path, "--category", "x"])[1], "2024-03-09 x 5.00 a  b\n")

    def test_add_keeps_separator_characters_in_note(self):
        for ch in ("\x0c", "\u2028", "\x85"):
            p = self.write("sep.txt", "")
            code, out, err = run(["add", p, "2024-03-09", "x", "5", "a%sb" % ch])
            self.assertEqual((code, out, err), (0, "2024-03-09 x 5.00 a%sb\n" % ch, ""), repr(ch))
            self.assertEqual(self.read(p), ("2024-03-09 x 5.00 a%sb\n" % ch).encode("utf-8"))
            code, out, _ = run(["list", p])
            self.assertEqual((code, out), (0, "2024-03-09 x 5.00 a%sb\n" % ch), repr(ch))

